INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66222630', 66222630, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Belanja Bahan dukungan Sosialisasi dan advokasi pada masyarakat mengenai fasilitas pelayanan kesehatan dalam penanganan penyakit infeksius dan KJSU berupa Kit Peserta', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 1152000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12800.0 PT', 'Paket pekerjaan ini berupa pengadaan kit peserta dalam bentuk kaos yang akan digunakan pada kegiatan sosialisasi dan advokasi kepada masyarakat mengenai fasilitas pelayanan kesehatan dalam penanganan penyakit infeksius dan KJSU (Kanker, Jantung, Stroke, dan Uronefrologi). Pekerjaan meliputi perencanaan desain, produksi, pengemasan, dan pengiriman kaos kepada panitia kegiatan sesuai jumlah peserta yang ditetapkan. Kaos diharapkan dapat mendukung identitas kegiatan, meningkatkan partisipasi peserta, serta menjadi media informasi dan promosi kesehatan kepada masyarakat.', 'Spesifikasi: Warna: Misty/Abu Muda; Bahan: Katun Combet 24s; Cetak: Plastisol; Logo: Menggunakan label di kerah (3,5 x 8,2 cm); Finishing: Lipat kemas plastik; Logo Kemenkes pada lengan kanan (6 x 6 cm); Logo DPR RI pada lengan kiri (6 x 6 cm); Bagian dada diberi tulisan; 1) GERMAS (Tipe font: Allstar Reguler 13 x 3,5 cm); 2) Nama Anggota DPR (Nma DPR) (Tipe Font: Oswald Medium, 52 point; 3) Jabatan Anggota DPR (Tipe Font: Oswald Medium, 40 point).', 1152000000, 'absurd', 'Pengadaan kit peserta berupa kaos untuk sosialisasi kesehatan memuat identitas dan jabatan anggota DPR pada desain barang. Penggunaan anggaran kesehatan untuk media promosi yang menonjolkan figur/jabatan politik menimbulkan indikasi kuat ketidakpatutan dan berisiko tidak relevan dengan tujuan utama layanan publik. Seluruh nilai pengadaan patut dicermati sebagai potensi pemborosan karena manfaat program substantifnya tidak jelas dibanding fungsi promosi personal.', NULL, NULL, 4, 1, 1, 1, 1, 2630214);
