INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66223679', 66223679, 'analyze_legacy', 'Aceh', 'central', 'Dinas Sosial', 'PENGAWASAN PEKERJAAN PEMASANGAN ATAP PENUTUP HALAMAN GEDUNG', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Aceh, Banda Aceh (Kota)', 4000000, 'March 2026', 'APBD', 1, 1, '1 Paket', 'Jasa Pengasawan PEMASANGAN ATAP PENUTUP HALAMAN GEDUNG', '-', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2630643);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66260040', 66260040, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'BALAI PELATIHAN DAN PENGEMBANGAN TEKNOLOGI INFORMASI DAN KOMUNIKASI', 'Pemeliharaan Gedung Asrama (A, B, dan C) dan Fasilitas Pendopo BPT Komdigi', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Jawa Barat, Bekasi (Kab.)', 392000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pekerjaan ini merupakan kegiatan pemeliharaan bangunan pada Gedung Asrama (Gedung A, B, dan C) serta penataan bangunan terbuka/pendopo di lingkungan Balai Pelatihan Talenta Komunikasi dan Digital. Kegiatan meliputi perbaikan plafon area luar gedung asrama yang mengalami kerusakan akibat paparan air hujan, perbaikan sistem perpipaan air bersih pada area toilet Gedung C, pekerjaan pengecatan ulang Gedung C, serta penataan bangunan terbuka/pendopo melalui pemasangan bagian penutup tambahan untuk mengurangi tampias air hujan. Pekerjaan juga mencakup kegiatan pembongkaran pada bagian bangunan yang terdampak pekerjaan instalasi, pemasangan kembali bagian arsitektur yang dibongkar, serta pembersihan area kerja setelah pekerjaan selesai dilaksanakan.', 'Spesifikasi pekerjaan secara umum meliputi pelaksanaan pekerjaan konstruksi pemeliharaan bangunan dengan ketentuan sebagai berikut: Perbaikan plafon area luar Gedung Asrama A, B, dan C dengan melakukan pembongkaran plafon yang rusak, perbaikan atau penggantian rangka plafon yang mengalami korosi, serta pemasangan plafon baru sesuai standar teknis pekerjaan bangunan gedung. Perbaikan sistem perpipaan air bersih pada area toilet Gedung C melalui pembongkaran jalur pipa eksisting yang sudah tidak layak serta pemasangan pipa baru menggunakan material pipa PPR PN 10 lengkap dengan fitting, aksesoris, dan valve yang diperlukan. Pelaksanaan pekerjaan arsitektur pendukung instalasi perpipaan yang meliputi pembukaan akses pada bagian bangunan, pembongkaran dan pemasangan kembali plafon PVC pada area kamar mandi, perbaikan dinding dan keramik yang terdampak pekerjaan, serta pembuatan mainhole dengan pintu akses untuk pemeliharaan pipa. Pengecatan ulang Gedung C yang meliputi persiapan permukaan dinding, perbaikan bagian dinding yang mengalami kerusakan, serta aplikasi cat sesuai standar pekerjaan pengecatan bangunan. Penataan bangunan terbuka/pendopo melalui pemasangan bagian penutup atau plafon tambahan guna mengurangi tampias air hujan pada area tengah bangunan sehingga meningkatkan kenyamanan penggunaan ruang. Seluruh pekerjaan dilaksanakan sesuai spesifikasi teknis, gambar kerja, serta standar mutu pekerjaan konstruksi bangunan gedung yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2630644);
