INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66266488', 66266488, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Konsumsi Rapat Biasa Layanan Peliputan dan Dokumentasi Program Kemnaker', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 52500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1000 OK', 'Pengadaan ini mencakup penyediaan konsumsi rapat biasa untuk mendukung kelancaran pelaksanaan layanan peliputan dan dokumentasi Program Kementerian Ketenagakerjaan, berupa snack/coffee break dan/atau makan (nasi kotak/prasmanan sesuai kebutuhan) bagi peserta/panitia pada waktu dan lokasi yang ditentukan, termasuk persiapan, pengemasan, pengantaran, penataan sederhana, serta penggantian apabila terdapat kekurangan jumlah atau ketidaksesuaian kualitas; pelaksanaan dilakukan berdasarkan permintaan/undangan rapat dan daftar hadir, dengan penagihan didukung bukti serah terima/BA dan dokumentasi pelaksanaan.', 'Konsumsi wajib memenuhi standar higiene-sanitasi (diproduksi di dapur/penyedia yang bersih, makanan layak konsumsi, bebas bau/tengik, dan aman), menggunakan kemasan food grade yang rapi dan tertutup, porsi memadai dan konsisten, menu bervariasi (tersedia opsi ayam/ikan/sayur, sambal/pelengkap, buah/air mineral; snack minimal 2 jenis kue/jajanan), minuman (air mineral/teh/kopi) sesuai permintaan, seluruh makanan halal (dibuktikan/ dinyatakan oleh penyedia), serta pengantaran tepat waktu sesuai jam rapat (toleransi keterlambatan minimal) dengan jumlah sesuai pesanan dan cadangan untuk antisipasi; bila ditemukan ketidaksesuaian (jumlah kurang, kemasan rusak, kualitas tidak layak), penyedia wajib mengganti pada hari yang sama tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2636185);
