INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66266602', 66266602, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Alat Tulis Kantor Monitoring dan Analisis Berita', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 9000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '12 Kegiatan', 'Pengadaan Alat Tulis Kantor (ATK) untuk mendukung pelaksanaan kegiatan Monitoring dan Analisis Berita di lingkungan Biro Humas, meliputi penyediaan kebutuhan ATK operasional untuk pencatatan, pengolahan dan pengarsipan data/kliping, pencetakan dan penyusunan laporan monitoring, serta dukungan administrasi koordinasi internal; pekerjaan mencakup penyiapan daftar kebutuhan sesuai perencanaan, penyediaan barang, pengemasan, pengiriman ke lokasi yang ditentukan, pemeriksaan kuantitas/kualitas pada saat serah terima, serta penggantian apabila terdapat barang rusak, tidak sesuai spesifikasi, atau kurang jumlahnya sesuai ketentuan yang berlaku.', 'Kelompok barang habis pakai dan perlengkapan perkantoran seperti kertas HVS (minimal A4, gramasi 70–80 gsm), alat tulis (pulpen/pensil), penanda (stabilo/spidol), perlengkapan koreksi (correction tape/tipe-x), catatan (buku/sticky notes), pengarsipan (map/ordner/stopmap), pengikat dokumen (paper clip/binder clip/stapler beserta isi), perlengkapan potong/rekat (gunting/lem/label), bahan cetak printer berupa tinta/toner yang kompatibel dengan perangkat yang digunakan satuan kerja, serta ATK lainnya; seluruh barang wajib kondisi baru (bukan rekondisi), kemasan pabrikan, kualitas baik dan layak pakai, ukuran/jenis sesuai standar perkantoran, serta diperbolehkan “atau ekuivalen” sepanjang memenuhi/lebih tinggi dari parameter fungsi dan mutu yang dipersyaratkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2637149);
