INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66267656', 66267656, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Komputer Suplies Kegiatan Fasilitasi dan Koordinasi Kerjasama dengan Lembaga Tinggi Negara, Pemerintah, dan Lembaga Non Pemerintah.', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 12600000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '12 Kegiatan', 'Pengadaan komputer suplies untuk mendukung kelancaran pelaksanaan kegiatan fasilitasi dan koordinasi kerja sama Biro Humas Kementerian Ketenagakerjaan dengan Lembaga Tinggi Negara, pemerintah, dan lembaga non-pemerintah, berupa penyediaan perlengkapan penunjang operasional perangkat TIK/perkantoran yang digunakan dalam persiapan bahan koordinasi, korespondensi, penggandaan dokumen, pelaksanaan rapat/FGD, serta pengelolaan arsip dan dokumentasi kegiatan. Pekerjaan meliputi pengadaan dan pengiriman barang sesuai daftar kebutuhan, penyesuaian jumlah berdasarkan kebutuhan riil kegiatan, serta memastikan barang diterima dalam kondisi baru, layak pakai, dan dapat digunakan untuk mendukung output koordinasi/komunikasi kelembagaan secara tepat waktu.', 'Spesifikasi pengadaan mencakup komputer suplies/perlengkapan pendukung perangkat komputer dan perkantoran yang bersifat habis pakai maupun aksesoris ringan, seperti tinta/toner/katrid yang kompatibel dengan perangkat yang digunakan unit kerja, kertas printer dan perlengkapan cetak, media penyimpanan data, kabel/konektor/adapter sederhana, serta peripheral pendukung (mis. mouse/keyboard) sesuai kebutuhan operasional; seluruh barang wajib berstatus baru, tidak rekondisi, tidak kedaluwarsa (untuk consumables), kemasan baik, kompatibel dengan perangkat eksisting, dan memenuhi standar mutu pabrikan/SNI atau standar yang setara bila relevan. Penyedia wajib melakukan pengemasan dan pengiriman aman sampai lokasi serah terima, disertai dokumen penyerahan (BAST) dan bukti kesesuaian barang (lembar spesifikasi/label/garansi jika ada) sesuai ketentuan pengadaan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2637875);
