INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66266960', 66266960, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Fotocopy/Penggandaan dan Penjilidan Monitoring dan Analisis Berita', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 1680000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '12 Kegiatan', 'layanan fotokopi/penggandaan dan penjilidan dokumen pendukung Kegiatan Monitoring dan Analisis Berita, termasuk pencetakan ulang/penyalinan dari naskah atau berkas yang diserahkan oleh Biro Humas, penyusunan urutan dokumen sesuai instruksi (tanggal, topik, jenis media, atau kebutuhan pelaporan), pengelompokan per paket laporan, pemberian pemisah/label bila diperlukan, proses finishing (rapi, presisi, tidak terpotong/terbalik), serta pengemasan dan penyerahan hasil kepada Pejabat Pembuat Komitmen/Pengelola kegiatan sesuai jadwal dan kebutuhan operasional untuk keperluan dokumentasi, diseminasi internal, dan arsip.', 'penggandaan dokumen pada ukuran kertas A4 dan/atau F4 sesuai permintaan, opsi hitam-putih dan/atau berwarna sesuai kebutuhan konten, hasil cetak jelas terbaca (tidak pudar/berbayang), rapi dan konsisten (margin tidak terpotong, posisi tidak miring, tidak ada halaman kosong/terlewat), penyusunan halaman sesuai urutan yang ditetapkan, serta penjilidan rapi dan kuat (misalnya jilid lem panas/spiral/lakban sesuai ketebalan dokumen) dengan cover depan–belakang bila diperlukan, disertai penandaan judul/periode pada sampul atau punggung jilid; seluruh dokumen wajib dijaga kerahasiaannya, dan hasil akhir diserahkan dalam kondisi bersih, tidak kusut, dan siap digunakan/diarsipkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2638010);
