INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66267584', 66267584, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Alat Tulis Kantor Fasilitasi dan Koordinasi Kerjasama dengan Lembaga Tinggi Negara, Pemerintah, dan Lembaga Non Pemerintah', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 9000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '12 Kegiatan', 'Pengadaan Alat Tulis Kantor (ATK) ini dilaksanakan untuk memenuhi kebutuhan barang habis pakai perkantoran yang digunakan secara langsung dalam pelaksanaan kegiatan fasilitasi dan koordinasi kerja sama Biro Humas Kementerian Ketenagakerjaan dengan Lembaga Tinggi Negara, pemerintah, dan lembaga non pemerintah, meliputi dukungan administrasi persuratan, penyusunan dan penggandaan bahan rapat, pencatatan/notulensi, pengarsipan dokumen, serta kebutuhan operasional rapat/koordinasi lainnya; penyedia wajib menyediakan, mengemas, dan menyerahkan ATK sesuai permintaan dan jadwal yang ditetapkan Pejabat Pembuat Komitmen/PPK, serta menjamin barang diterima dalam kondisi baik dan dapat digunakan.', 'ATK yang disediakan merupakan barang baru, layak pakai, tidak cacat, dan sesuai standar mutu perkantoran, terdiri dari item-item ATK umum (misalnya kertas HVS berbagai ukuran/gramasi sesuai kebutuhan, pulpen/pensil/spidol, buku catatan, map/ordner/folder, amplop, lem/isolasi, stapler dan isi staples, paper clip/binder clip, tinta/toner bila termasuk kebutuhan administrasi, serta perlengkapan pendukung administrasi lainnya) dengan ketentuan: ukuran/jenis/warna disesuaikan kebutuhan unit kerja, kemasan rapi dan aman, mencantumkan informasi produk yang wajar (jenis/ukuran), dan seluruh item harus kompatibel dengan penggunaan perkantoran sehari-hari; serah terima dilakukan berdasarkan daftar item dan jumlah (rincian kebutuhan) yang disepakati, dibuktikan dengan berita acara/daftar penerimaan barang setelah verifikasi kesesuaian jumlah dan kualitas.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2638288);
