INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66267010', 66267010, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'DIREKTORAT JENDERAL KEPENDUDUKAN DAN PENCATATAN SIPIL', 'Pramubakti', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 55130000, 'March 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '10 OB', '1. Menjaga kerapihan ruangan, seperti merapikan dokumen atau barang yang tidak pada tempatnya. 2. Mengelola sampah, termasuk mengganti kantong sampah secara rutin dan memastikan area tetap bebas dari limbah. 3. Menyediakan kebutuhan rapat, seperti menyiapkan meja, kursi, alat tulis, dan perlengkapan lainnya. 4. Mengisi ulang kebutuhan dasar kantor, seperti air minum, sabun, tisu, dan perlengkapan kebersihan. 5. Membantu dalam proses pengangkutan dokumen atau barang ringan antar divisi. 6. Memeriksa kondisi fasilitas seperti lampu, AC, pintu, dan peralatan lain yang membutuhkan perhatian', '1. Minimal pendidikan SMA/sederajat, diutamakan memiliki pengalaman kerja sebagai pramubakti, office support, cleaning service, atau tugas kerumahtanggaan lainnya minimal 1 (satu) tahun; 2. Memiliki pengetahuan mengenai kebersihan ruang kantor, penataan ruang, dan penggunaan peralatan kebersihan; 3. Mampu bekerja dengan rapi, cepat, dan teliti, termasuk dalam penataan ruang rapat, distribusi dokumen, serta dukungan logistik kantor; 4. Memiliki kemampuan bahasa dan komunikasi yang baik; 5. Berdisiplin, bertanggung jawab, dan memiliki etika kerja yang baik, termasuk menjaga kerahasiaan informasi kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2638554);
