INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66267032', 66267032, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'DIREKTORAT JENDERAL KEPENDUDUKAN DAN PENCATATAN SIPIL', 'Pengemudi', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 60650000, 'March 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '10 OB', 'Pengemudi II Ruang lingkup pekerjaan Pengemudi adalah sebagai berikut: 1. Melaksanakan tugas mengemudi untuk mendukung mobilitas pimpinan, pegawai, serta pelaksanaan kegiatan operasional sesuai dengan jadwal dan arahan yang diberikan; 2. Menjaga keselamatan dan keamanan perjalanan, termasuk memastikan kepatuhan terhadap rambu lalu lintas, prosedur keselamatan, serta kondisi berkendara yang aman dan nyaman; 3. Melakukan pemeriksaan rutin kendaraan, seperti pengecekan bahan bakar, oli, ban, air radiator, lampu, dan kondisi umum kendaraan sebelum dan sesudah digunakan; 4. Menjaga kebersihan kendaraan, baik bagian dalam maupun luar, serta memastikan kendaraan selalu dalam kondisi siap pakai; 5. Mengantarkan dokumen penting atau barang dinas sesuai kebutuhan dan arahan atasan dengan tetap menjaga kerahasiaan dan keamanan dokumen.', '1. Memiliki SIM A yang masih berlaku dan memiliki pengalaman menyetir kendaraan roda empat minimal selama 2 tahun 2. Mampu mengemudikan kendaraan roda empat transmisi manual maupun otomatis 3. Memiliki penglihatan yang baik untuk mengemudikan kendaraan roda empat 4. Memiliki kemampuan bahasa dan komunikasi yang baik 5. Memahami sistem navigasi jika diperlukan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2638619);
