INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66266926', 66266926, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Komputer Suplies Monitoring dan Analisis Media', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 12600000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '12 Kegiatan', 'Pengadaan komputer supplies untuk mendukung kelancaran pelaksanaan kegiatan Monitoring dan Analisis Media pada Biro Humas Kemnaker, meliputi penyediaan dan pengiriman barang habis pakai serta aksesori/perlengkapan pendukung perangkat kerja (komputer dan perangkat penunjang) agar proses pengumpulan data, pengolahan, penyusunan laporan, dokumentasi, dan administrasi layanan monitoring dapat berjalan efektif dan berkesinambungan; pekerjaan mencakup pemenuhan kebutuhan sesuai daftar dan jumlah pada dokumen pemesanan/kontrak, pengantaran ke lokasi yang ditentukan, pemeriksaan kesesuaian/kelayakan barang, serta serah terima dan penggantian apabila ditemukan ketidaksesuaian atau kerusakan pada saat penerimaan.', 'Komputer supplies yang disediakan wajib baru, layak pakai, bukan rekondisi/bekas, dan memenuhi standar mutu pabrikan serta kompatibel dengan perangkat yang digunakan satker; spesifikasi minimal mencakup (sesuai kebutuhan pada surat pesanan) antara lain consumables/perlengkapan operasional seperti kertas cetak (ukuran dan gramasi sesuai kebutuhan), tinta/toner/cartridge yang sesuai tipe perangkat dan memiliki kualitas cetak baik, media penyimpanan (flashdisk/HDD/SSD eksternal) dengan kapasitas sesuai kebutuhan dan kondisi sehat, aksesori komputer (mouse/keyboard/kabel/adapter) yang berfungsi normal, serta perlengkapan pendukung/maintenance ringan (mis. pembersih perangkat) bila diperlukan; seluruh barang diserahkan dalam kemasan baik, disertai dokumen pengiriman, dan diberikan jaminan penggantian untuk barang cacat/tidak sesuai pada saat pemeriksaan penerimaan, dengan penganggaran tetap mengacu pada ketentuan standar biaya/komponen yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2638657);
