INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66267004', 66267004, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'DIREKTORAT JENDERAL KEPENDUDUKAN DAN PENCATATAN SIPIL', 'Tenaga Kebersihan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 55130000, 'March 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '10 OB', '1. Melaksanakan pembersihan harian di seluruh area kantor, termasuk ruang kerja, ruang rapat, lorong, area pelayanan, toilet, dan fasilitas umum lainnya. 2. Melakukan pembersihan berkala seperti pembersihan kaca, peralatan kantor, ventilasi, dan area yang jarang dijangkau sesuai jadwal yang ditetapkan. 3. Menjaga kerapihan dan kebersihan ruang rapat sebelum dan sesudah digunakan, termasuk menata kursi, meja, dan perlengkapan pendukung. 4. Mengelola dan memastikan ketersediaan perlengkapan kebersihan, termasuk mengisi ulang sabun, tisu, dan kebutuhan sanitasi lainnya. 5. Mengumpulkan dan membuang sampah secara rutin sesuai prosedur, termasuk memilah sampah jika diperlukan.', '1. Minimal pendidikan SMA/sederajat, diutamakan memiliki pengalaman kerja sebagai Tenaga Kebersihan, office support, cleaning service, atau tugas kerumahtanggaan lainnya minimal 1 (satu) tahun; 2. Memiliki pengetahuan dasar terkait teknik kebersihan, penggunaan alat kebersihan, bahan pembersih, dan prosedur sanitasi ruangan; 3. Mampu bekerja secara rapi, teliti, dan cekatan, termasuk dalam penanganan kebersihan ruang kerja, ruang rapat, area pelayanan, dan fasilitas umum; 4. Memiliki kemampuan bahasa dan komunikasi yang baik; 5. Berdisiplin, bertanggung jawab, dan memiliki etika kerja yang baik, termasuk menjaga kerahasiaan informasi kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2638751);
