INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66267699', 66267699, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Fotocopy/Penggandaan dan Penjilidan Fasilitasi dan Koordinasi Kerjasama dengan Lembaga Tinggi Negara, Pemerintah, dan Lembaga Non Pemerintah.', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 1680000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '12 Kegiatan', 'Layanan fotocopy/penggandaan dokumen dan penjilidan untuk mendukung pelaksanaan Kegiatan Fasilitasi dan Koordinasi Kerja Sama dengan Lembaga Tinggi Negara, Pemerintah, dan Lembaga Non Pemerintah, meliputi penggandaan bahan rapat/audiensi/koordinasi (antara lain undangan, agenda, TOR, bahan paparan, risalah/notula, daftar hadir, lembar disposisi, surat-menyurat, dan lampiran administrasi lainnya), penyusunan set dokumen sesuai kebutuhan unit kerja, serta penjilidan/finishing dokumen agar rapi, mudah didistribusikan, dan terdokumentasi, dengan pelaksanaan layanan berdasarkan permintaan (order) dari PPK/pejabat yang ditunjuk dan penyelesaian tepat waktu sesuai jadwal kegiatan.', 'Penggandaan/penyalinan dokumen hitam-putih dan/atau berwarna pada kertas ukuran A4 dan/atau F4 sesuai permintaan, hasil cetak jelas dan terbaca, presisi potong rapi, tidak buram/belepotan, serta pengaturan halaman (urut, bolak-balik/duplex bila diminta, pemisahan per set, dan penyertaan cover/lembar pembatas bila diperlukan); penjilidan meliputi minimal stapler, jilid lakban, spiral, atau binding (sesuai permintaan) dengan hasil kokoh dan rapi; termasuk layanan finishing seperti penyusunan per pak