INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66232010', 66232010, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'KANTOR PUSAT SEKRETARIAT JENDERAL', 'Sewa Platform dan Sistem pendukung DRC', 'Jasa Lainnya', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 15184245000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '1, PT', 'Sewa Platform dan Sistem pendukung DRC', 'Deskripsi kebutuhan dari pengadaan Sewa Platform dan Sistem Pendukung Disaster Recovery Center (DRC) sebagai berikut: 1. Tersedianya jasa instalasi, konfigurasi, dan replikasi terkait layanan platform dan sistem pendukung Disaster Recovery Center (DRC). 2. Tersedianya software berlisensi sebagai sistem pendukung DC-DRC dan backup data sehingga aplikasi layanan berjalan dengan normal di fasilitas DRC. 3. Tersedianya layanan jaringan koneksi untuk menghubungkan antara Data Center Utama dengan Disaster Recovery Center dan koneksi internet agar informasi yang tersimpan dalam server di DRC tersebut tetap dapat diakses. 4. Layanan infrastruktur beserta manage service nya sebagai resource di DRC. 5. Infrastruktur backup data berlapis beserta manage service nya di Data Center utama dan DRC. 6. Tersedianya infrastruktur backup data Satu Sehat platform Kemenkes dari Google Cloud Platform pada lokasi DRC. 7. Tersedianya dukungan tenaga kerja yang ahli untuk operasional di selama 24 jam x 7 hari. 8. Tersedianya dukungan engineer on site untuk memantau dan melaporkan jalannya operasional layanan. 9. Pelaksanaan alih pengetahuan terhadap teknologi yang digunakan kepada sejumlah 8 orang sebanyak 2 kali selama tahun anggaran berjalan. 10. Pelaksanaan business continuity planning DRC sebanyak 4 kali selama tahun anggaran berjalan. 11. Pelaksanaan finalisasi dokumen BCM melalui pertemuan sebanyak 1 kali selama tahun anggaran berjalan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2639890);
